NEW:
    function computeSilenceWaitMs(text) {
      const base = Number(settings.silenceAutoSendMs || 0);
      if (!base) return 0;
      const trimmed = String(text || '').replace(/\s+/g, ' ').trim();
      let score = 50;
      if (/[.!?\u2026]\s*$/.test(trimmed)) score += 35;
      else score -= 15;
      if (/\b(um|uh|like|you know)[.!?\u2026]?\s*$/i.test(trimmed)) score -= 35;
      else score += 15;
      score = Math.min(100, Math.max(0, score));
      const factor = 1.6 - (score / 100) * 1.2;
      return Math.max(200, Math.round(base * factor));
    }

    function scheduleSilenceAutoSend() {
      const ms = Number(settings.silenceAutoSendMs || 0);
      if (!ms || ms <= 0 || typeof settings.onAutoSend !== 'function') return;
      clearSilenceTimer();
      const wait = computeSilenceWaitMs(input && input.value);
      state.silenceTimer = global.setTimeout(() => {
        state.silenceTimer = null;
        fireAutoSend('silence');
      }, wait);
    }

computeSilenceWaitMs mirrors the trailingPunctuation and trailingFillerWord scoring factors from services/interaction-decision-service.js's computeTurnCompletionConfidence (same regexes, same +35/-15 and -35/+15 weights) but starts from a neutral score=50 baseline instead of that function's pauseMs/finalTranscript-driven baseline, because at the moment scheduleSilenceAutoSend fires the pause has not happened yet -- we are choosing how long to WAIT, not scoring a pause that already completed. A finished-sounding statement (trailing punctuation, no trailing filler word, score near 100) waits close to 0.4x the configured settings.silenceAutoSendMs; a mid-thought statement (trailing filler word or no punctuation, score near 0) waits close to 1.6x it, so the user gets more room to keep talking. A 200ms floor prevents a pathologically short wait. This is the real fix for the audit finding that the turn-completion confidence algorithm built in CV1P-S01 had zero live callers -- the barge-in/interruption side (CV1P-S02/S03) was wired, but the turn-taking/auto-send side never used it.
